package com.example.examplemod;

import net.minecraft.world.entity.monster.Creeper;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.Mod;
import net.neoforged.neoforge.event.entity.EntityJoinLevelEvent;

@Mod.EventBusSubscriber(modid = ExampleMod.MODID)
public class JoinHandlers {

    // EntityJoinWorldEvent was renamed to EntityJoinLevelEvent when World became Level
    // (that rename already existed in 1.20.1 - mods still shipping the old name now
    // get a hard compile error against NeoForge 1.21.1).
    @SubscribeEvent
    public static void onJoin(EntityJoinLevelEvent event) {
        if (event.getEntity() instanceof Creeper) {
            event.setCanceled(true);
        }
    }
}

