import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.CrowdBlockEntity;

public class CrowdBER implements BlockEntityRenderer<CrowdBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public CrowdBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    // rotating parts exceed the 1x1x1 block bounds: vanilla culling would
    // pop the whole render when the block is off-screen; infinite box opts out
    @Override
    public AABB getRenderBoundingBox() {
        return AABB.infinite();
    }

    @Override
    public void render(CrowdBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        for (int i = 0; i < 24; i++) {
            if (be.isHidden()) continue;
            double a = Math.toRadians(i * 15.0);
            pose.pushPose();
            pose.translate(0.5 + Math.cos(a) * 0.6, 0.1,
                    0.5 + Math.sin(a) * 0.6);
            pose.scale(0.05f, 0.05f, 0.05f);
            ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                    Blocks.EMERALD_BLOCK.defaultBlockState(), pose, buffers,
                    light, OverlayTexture.NO_OVERLAY);
            pose.popPose();
        }
    }
}

package com.example.examplemod.client.render;

public class FrustumDoc {
    // conservative: real culling uses camera-space frustum planes; this
    // distance test never hides a sphere that is actually visible
    public static boolean sphereIntersectsFrustumLike(
            double cx, double cy, double cz, double radius,
            double camX, double camY, double camZ, double maxDist) {
        double dx = cx - camX, dy = cy - camY, dz = cz - camZ;
        double limit = maxDist + radius;
        return dx * dx + dy * dy + dz * dz <= limit * limit;
    }

    public static double maxSafeRadius() {
        return 32.0;
    }
}

package com.example.examplemod.client.render;

import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.blockentity.BlockEntityRenderer;
import net.minecraft.client.renderer.blockentity.BlockEntityRendererProvider;
import net.minecraft.client.renderer.texture.OverlayTexture;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;

import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.LazyModelBlockEntity;

public class LazyModelBER implements BlockEntityRenderer<LazyModelBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;
    private Integer cachedKey;
    private BlockState cachedState;

    public LazyModelBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    private BlockState stateFor(int variant) {
        if (cachedKey == null || cachedKey != variant) {
            cachedKey = variant;
            cachedState = switch (Math.floorMod(variant, 3)) {
                case 0 -> Blocks.STONE.defaultBlockState();
                case 1 -> Blocks.COBBLESTONE.defaultBlockState();
                default -> Blocks.MOSSY_COBBLESTONE.defaultBlockState();
            };
        }
        return cachedState;
    }

    @Override
    public void render(LazyModelBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        // note: on resource reload the cached state must be re-resolved;
        // the reload hook is out of scope for this exercise
        BlockState state = stateFor(be.getVariant());
        pose.pushPose();
        pose.translate(0.5, 0.15, 0.5);
        pose.scale(0.7f, 0.7f, 0.7f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                state, pose, buffers, light, OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

package com.example.examplemod.client.render;

public class PoseStackAudit {
    // a leaked pushPose corrupts every subsequent render in the frame:
    // transforms accumulate and geometry drifts or disappears
    public static int audit(String[] ops) {
        int depth = 0;
        for (String op : ops) {
            if ("push".equals(op)) depth++;
            else if ("pop".equals(op)) depth--;
        }
        return depth;
    }

    public static boolean isBalanced(String[] ops) {
        return audit(ops) == 0;
    }

    public static String diagnose(String[] ops) {
        int depth = 0;
        for (String op : ops) {
            if ("push".equals(op)) depth++;
            else if ("pop".equals(op)) {
                depth--;
                if (depth < 0) return "underflow";
            }
        }
        return depth == 0 ? "ok" : "leak";
    }
}

