public class CompatGuard {
    // render hooks must degrade gracefully (not crash) when a mod replaces
    // the model pipeline
    public static boolean canApplyCustomModel(String otherModId) {
        String id = otherModId == null ? "" : otherModId.toLowerCase();
        return !id.equals("optifine") && !id.equals("sodium_official");
    }

    public static String conflictReason(String otherModId) {
        String id = otherModId == null ? "" : otherModId.toLowerCase();
        if (id.equals("optifine") || id.equals("sodium_official")) {
            return "pipeline_replacement";
