import com.mojang.blaze3d.vertex.PoseStack;
import com.example.examplemod.block.entity.SafeRotBlockEntity;

public class SafeRotationBER implements BlockEntityRenderer<SafeRotBlockEntity> {
    private final BlockEntityRendererProvider.Context ctx;

    public SafeRotationBER(BlockEntityRendererProvider.Context ctx) {
        this.ctx = ctx;
    }

    @Override
    public void render(SafeRotBlockEntity be, float partialTick, PoseStack pose,
                       MultiBufferSource buffers, int light, int overlay) {
        long t = be.getLevel() != null ? be.getLevel().getGameTime() : 0;
        float dy = RenderLoopBudget.fastSinDeg((int) ((t * 6) % 360)) * 0.1f;
        pose.pushPose();
        pose.translate(0.5, 0.3 + Math.abs(dy), 0.5);
        pose.scale(0.4f, 0.4f, 0.4f);
        ctx.getBlockRenderDispatcher().getBlockRenderer().renderSingleBlock(
                Blocks.GOLD_BLOCK.defaultBlockState(), pose, buffers, light,
                OverlayTexture.NO_OVERLAY);
        pose.popPose();
    }
}

