public class BlockBreakGuard {
    public static boolean canBreak(Level level, BlockPos pos, Player p) {
        if (level.isClientSide) return false;
        if (!level.isLoaded(pos)) return false; // unloaded chunk
        if (level.getBlockState(pos).getBlock() == Blocks.BEDROCK) {
            return false;
        }
        return true;
    }
}

package com.example.examplemod.gameplay;

import net.minecraft.core.BlockPos;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ChunkReloadState {
    // unload may race with ticking; concurrent map keeps this safe
    private static final Map<String, Integer> store = new ConcurrentHashMap<>();

    public static void onUnload(String worldKey, BlockPos pos, int charge) {
        store.put(worldKey + ":" + pos.asLong(), charge);
    }

    public static Integer onReload(String worldKey, BlockPos pos) {
        return store.remove(worldKey + ":" + pos.asLong());
    }
}

