public class RegistryMissingGuard {
    private static final Pattern VALID = Pattern.compile("[a-z0-9_]+:[a-z0-9_/]+");

    // saved ids may vanish when a mod updates: fall back gracefully
    public static String safeResolve(String id, String fallback) {
        if (id == null) return fallback;
        return VALID.matcher(id).matches() ? id : fallback;
    }
}

