import net.minecraft.resources.ResourceLocation;

public record MoveBlockPayload(double x, double y, double z)
        implements CustomPacketPayload {

    public static final Type<MoveBlockPayload> TYPE =
            new Type<>(ResourceLocation.fromNamespaceAndPath(
                    "examplemod", "move_block"));

    public static final StreamCodec<ByteBuf, MoveBlockPayload> STREAM_CODEC =
            StreamCodec.composite(
                    ByteBufCodecs.DOUBLE, MoveBlockPayload::x,
                    ByteBufCodecs.DOUBLE, MoveBlockPayload::y,
                    ByteBufCodecs.DOUBLE, MoveBlockPayload::z,
                    MoveBlockPayload::new);

    @Override
    public Type<? extends CustomPacketPayload> type() {
        return TYPE;
    }

    public static void validateOrThrow(MoveBlockPayload p) {
        if (Double.isNaN(p.x) || Double.isNaN(p.y) || Double.isNaN(p.z)
                || Double.isInfinite(p.x) || Double.isInfinite(p.y)
                || Double.isInfinite(p.z)) {
            throw new IllegalArgumentException("non-finite coordinate");
        }
        if (Math.abs(p.x) > 30_000_000 || Math.abs(p.y) > 30_000_000
                || Math.abs(p.z) > 30_000_000) {
            throw new IllegalArgumentException("coordinate out of world range");
        }
    }
}

